solution_type:
∀ {M : Type audit_universe_0} [inst : Lean.Grind.IntModule.{audit_universe_0} M] {φ : Type audit_universe_1}
  {ρ : Type audit_universe_2} (features : List.{audit_universe_1} φ) (weight : φ → M)
  (certificate : List.{audit_universe_2} (Prod.{0, audit_universe_2} Nat ρ)) (delta : ρ → φ → Int),
  @Eq.{audit_universe_0 + 1} M
    (@CollatzWork.YAH.evalCoefficients.{audit_universe_0, audit_universe_1} φ M inst features weight
      (@CollatzWork.YAH.weightedCoefficient.{audit_universe_2, audit_universe_1 + 1} ρ φ certificate delta))
    (@CollatzWork.YAH.weightedGapSum.{audit_universe_0, audit_universe_2} ρ M
      (@Lean.Grind.IntModule.toNatModule.{audit_universe_0} M inst) certificate fun row =>
      @CollatzWork.YAH.evalCoefficients.{audit_universe_0, audit_universe_1} φ M inst features weight (delta row))

